-- Creatures left with SmartAI and no script to run: ours that stopped qualifying, and any
-- the base data left in the same state.
UPDATE `creature_template` `t` SET `t`.`AIName` = '' WHERE `t`.`AIName` = 'SmartAI' AND `t`.`ScriptName` = '' AND NOT EXISTS (SELECT 1 FROM `smart_scripts` `s` WHERE `s`.`source_type` = 0 AND `s`.`entryorguid` = `t`.`entry`) AND NOT EXISTS (SELECT 1 FROM `smart_scripts` `s` JOIN `creature` `c` ON `c`.`guid` = -`s`.`entryorguid` WHERE `s`.`source_type` = 0 AND `s`.`entryorguid` < 0 AND `c`.`id` = `t`.`entry`);
